// Tier 2 (Atari) fixtures: base64 768-byte inputs plus the official .lmc
// oracle texts they must reproduce. Mirrors pal-fixtures.ts / lmc-fixtures.ts's
// embedding convention (base64-in-.ts sidesteps binary test-asset loading).
//
// MARIA_7800_PAL_B64 is generated by a throwaway script that parses the
// a7800p_colors table (and the NTSC_* macros it references) directly out of
// MAME's src/mame/atari/a7800.cpp at the pinned commit below, in the same
// order a7800p_colors lists them -- never hand-typed (mitigating
// hand-transcription risk on 768 values). TIA_2600_PAL_B64 is
// built by duplicating each of the 128 colors from the Wikipedia "List of
// video game console palettes" 2600 NTSC table (Lospec mirror
// atari-2600-ntsc-wikipedia) into adjacent pairs. One entry (hue 11, luma 0)
// uses 003c2c rather than the Lospec mirror's 00402c: the mirror carries a
// transcription typo at that cell (independently confirmed against
// MARIA_7800.lmc's electrically-related hue ramps and against every other
// source consulted), and using it would break byte-identity with the
// official TIA_2600.lmc for no reason other than propagating the error.
// TREBOR_COOL_PAL_B64 is a real-world 768-byte file: no official .lmc
// preset exists for any Trebor palette, so its golden entry asserts only
// parse+convert success, never byte-identity (see GOLDEN_PAIRS_TIER2's
// trailing breadth entry).

import { SystemId } from '../system';
import { FixtureSource } from './lmc-fixtures';

const RT4K_FIRMWARE_1510 =
  'https://cdn.jsdelivr.net/gh/retrotink-llc/firmware@main/RetroTINK-4K/Experimental/rt4k_1510.zip';
const firmwareLmc = (file: string): FixtureSource => ({
  url: RT4K_FIRMWARE_1510,
  pathInArchive: file,
});

// MAME commit d066f16134121f02a2fd9716582a17f8ee66f6d5, src/mame/atari/a7800.cpp.
export const MARIA_7800_PAL_SOURCE: FixtureSource = {
  url: 'https://raw.githubusercontent.com/mamedev/mame/d066f16134121f02a2fd9716582a17f8ee66f6d5/src/mame/atari/a7800.cpp',
  pathInArchive: 'src/mame/atari/a7800.cpp (a7800p_colors table)',
};
export const MARIA_7800_PAL_B64 =
  '';

// Lospec mirror atari-2600-ntsc-wikipedia (127 of 128 entries cross-checked
// against MARIA_7800.lmc's shared hue ramps and TIA_2600.lmc; see the
// module comment for the one corrected transcription error).
export const TIA_2600_PAL_SOURCE: FixtureSource = {
  url: 'https://lospec.com/palette-list/atari-2600-ntsc-wikipedia',
  pathInArchive: 'Wikipedia "List of video game console palettes" 2600 NTSC table (128 colors, duplicated)',
};
export const TIA_2600_PAL_B64 =
  '';

// MiSTer-devel/Atari7800_MiSTer commit 3dc43ee77c3ff538fc34a61293caaa7cbf5b642a,
// Palette/Trebors/NTSC/CALIBRATED/NTSC_CALIBRATED_COOL.pal. Breadth fixture
// only -- no official .lmc exists for any Trebor palette, so this asserts
// parse+convert success, never byte-identity.
export const TREBOR_COOL_PAL_SOURCE: FixtureSource = {
  url: 'https://raw.githubusercontent.com/MiSTer-devel/Atari7800_MiSTer/3dc43ee77c3ff538fc34a61293caaa7cbf5b642a/Palette/Trebors/NTSC/CALIBRATED/NTSC_CALIBRATED_COOL.pal',
  pathInArchive: 'Palette/Trebors/NTSC/CALIBRATED/NTSC_CALIBRATED_COOL.pal',
};
export const TREBOR_COOL_PAL_B64 =
  '';

